CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE TABLE events (ticker text PRIMARY KEY, series_ticker text NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL, mutually_exclusive boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL);
CREATE TABLE markets (ticker text PRIMARY KEY, event_ticker text NOT NULL REFERENCES events(ticker), series_ticker text NOT NULL, title text NOT NULL, subtitle text NOT NULL DEFAULT '', close_time timestamptz NOT NULL, status text NOT NULL, result text, strike_type text, updated_at timestamptz NOT NULL);
CREATE INDEX ON markets(event_ticker);
CREATE INDEX ON markets(close_time);
CREATE TABLE odds_snapshots (ts timestamptz NOT NULL, ticker text NOT NULL REFERENCES markets(ticker), yes_bid double precision NOT NULL CHECK (yes_bid BETWEEN 0 AND 1), yes_ask double precision NOT NULL CHECK (yes_ask BETWEEN yes_bid AND 1), mid double precision NOT NULL CHECK (mid BETWEEN 0 AND 1), volume_24h double precision CHECK (volume_24h >= 0), open_interest double precision CHECK (open_interest >= 0), PRIMARY KEY(ts,ticker));
SELECT create_hypertable('odds_snapshots','ts');
CREATE INDEX ON odds_snapshots(ticker,ts DESC);
CREATE TABLE prices (ts timestamptz NOT NULL, symbol text NOT NULL, close double precision NOT NULL, loaded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(ts,symbol));
SELECT create_hypertable('prices','ts');
CREATE INDEX ON prices(symbol,ts DESC);
CREATE TABLE allowed_tags (tag text PRIMARY KEY);
CREATE TABLE series_tags (series_ticker text NOT NULL, tag text NOT NULL REFERENCES allowed_tags(tag), source text NOT NULL CHECK (source IN ('gemini','manual')), reviewed boolean NOT NULL DEFAULT false, PRIMARY KEY(series_ticker,tag));
CREATE TABLE stock_tags (symbol text NOT NULL, tag text NOT NULL REFERENCES allowed_tags(tag), link_type text NOT NULL CHECK (link_type IN ('direct','measured','related')), PRIMARY KEY(symbol,tag));
CREATE TABLE measured_links (symbol text NOT NULL, driver text NOT NULL, b double precision NOT NULL, se double precision NOT NULL CHECK(se>=0), low double precision NOT NULL, high double precision NOT NULL, days integer NOT NULL, reliable boolean NOT NULL, computed_at timestamptz NOT NULL, PRIMARY KEY(symbol,driver));
CREATE TABLE settled_markets (ticker text PRIMARY KEY, category text NOT NULL, prob_24h_before double precision NOT NULL CHECK(prob_24h_before BETWEEN 0 AND 1), outcome integer NOT NULL CHECK(outcome IN (0,1)), close_time timestamptz NOT NULL, odds_time timestamptz NOT NULL, loaded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE holdings (session_id text NOT NULL, symbol text NOT NULL, value_usd numeric(18,2) NOT NULL CHECK(value_usd>0), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,symbol));
CREATE TABLE sector_tags (sector text NOT NULL, tag text NOT NULL REFERENCES allowed_tags(tag), PRIMARY KEY(sector,tag));
CREATE TABLE job_state (name text PRIMARY KEY, cursor text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE summaries (event_ticker text PRIMARY KEY REFERENCES events(ticker), text text NOT NULL, sources jsonb NOT NULL, input_data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE risk_factors (symbol text PRIMARY KEY, source_url text NOT NULL, text text NOT NULL, processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE briefings (session_id text NOT NULL, day date NOT NULL, text text NOT NULL, audio bytea, as_of timestamptz, PRIMARY KEY(session_id,day));
